import{_ as p,a0 as o,w as l,s as d,ao as r,I as i,x as t,a1 as a,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"ss：查看网络连接的另一种方法 | LCTT x X-CMD","titleTemplate":false,"description":"ss：查看网络连接的另一种方法 | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"ss：查看网络连接的另一种方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"ss：查看网络连接的另一种方法 | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170725 ss another way to get socket statistics","title":"ss：查看网络连接的另一种方法","tag":"201707","desc":""},"relativePath":"201707/20170725 ss another way to get socket statistics.md","filePath":"[post].md"}'),c={name:"201707/20170725 ss another way to get socket statistics.md"};function h(u,s,g,k,b,m){const e=o("Link");return l(),d("div",null,[s[13]||(s[13]=r(`<h1 id="ss-查看网络连接的另一种方法" tabindex="-1">ss：查看网络连接的另一种方法 <a class="header-anchor" href="#ss-查看网络连接的另一种方法" aria-label="Permalink to “ss：查看网络连接的另一种方法”">​</a></h1><p>在之前的文章中，我提到过 <code>ss</code>，它是 iproute2 包附带的另一个工具，允许你查询 socket 的有关统计信息。可以完成 <code>netstat</code> 同样的任务，但是，<code>ss</code> 稍微快一点而且命令更简短。</p><p>直接输入 <code>ss</code>，默认会显示与 <code>netstat</code> 同样的内容，并且输入类似的参数可以获取你想要的类似输出。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ss -t</span></span>
<span class="line"><span>State       Recv-Q Send-Q       Local Address:Port                        Peer Address:Port</span></span>
<span class="line"><span>ESTAB       0      0                127.0.0.1:postgresql                     127.0.0.1:48154</span></span>
<span class="line"><span>ESTAB       0      0            192.168.0.136:35296                      192.168.0.120:8009</span></span>
<span class="line"><span>ESTAB       0      0            192.168.0.136:47574                     173.194.74.189:https</span></span>
<span class="line"><span>[…]</span></span></code></pre></div><p><code>ss -t</code> 只显示 TCP 连接。<code>ss -u</code> 用于显示 UDP 连接，<code>-l</code> 参数只会显示监听的端口，而且可以进一步过滤到任何想要的信息。</p><p>我并没有测试所有可用参数，但是你甚至可以使用 <code>-K</code> 强制关闭 socket。</p><p><code>ss</code> 真正耀眼的地方是其内置的过滤能力。让我们列出所有端口为 22（ssh）的连接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ss state all sport = :ssh</span></span>
<span class="line"><span>Netid State      Recv-Q Send-Q     Local Address:Port                      Peer Address:Port</span></span>
<span class="line"><span>tcp   LISTEN     0      128                    *:ssh                                  *:*</span></span>
<span class="line"><span>tcp   ESTAB      0      0          192.168.0.136:ssh                      192.168.0.102:46540</span></span>
<span class="line"><span>tcp   LISTEN     0      128                   :::ssh                                 :::*</span></span></code></pre></div><p>如果只想看已建立的 socket（排除了 <em>listening</em> 和 <em>closed</em> ）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ss state connected sport = :ssh</span></span>
<span class="line"><span>Netid State      Recv-Q Send-Q     Local Address:Port                      Peer Address:Port</span></span>
<span class="line"><span>tcp   ESTAB      0      0          192.168.0.136:ssh                      192.168.0.102:46540</span></span></code></pre></div><p>类似的，可以列出指定的 host 或者 ip 段。例如，列出到达 74.125.0.0/16 子网的连接，这个子网属于 Google：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ss state all dst 74.125.0.0/16</span></span>
<span class="line"><span>Netid State      Recv-Q Send-Q     Local Address:Port                      Peer Address:Port</span></span>
<span class="line"><span>tcp   ESTAB      0      0          192.168.0.136:33616                   74.125.142.189:https</span></span>
<span class="line"><span>tcp   ESTAB      0      0          192.168.0.136:42034                    74.125.70.189:https</span></span>
<span class="line"><span>tcp   ESTAB      0      0          192.168.0.136:57408                   74.125.202.189:https</span></span></code></pre></div><p><code>ss</code>与 iptables 的语法非常相同，如果已经熟悉了其语法，<code>ss</code> 非常容易上手。也可以安装 iproute2-doc 包， 通过 <code>/usr/share/doc/iproute2-doc/ss.html</code> 获得完整文档。</p><p>还不快试试! 你就可以知道它有多棒。无论如何，让我输入的字符越少我越高兴。</p><hr>`,15)),i("p",null,[s[1]||(s[1]=t("via: ",-1)),a(e,{href:"https://insights.ubuntu.com/2017/07/25/ss-another-way-to-get-socket-statistics/"},{default:n(()=>[...s[0]||(s[0]=[t("https://insights.ubuntu.com/2017/07/25/ss-another-way-to-get-socket-statistics/",-1)])]),_:1})]),i("p",null,[s[5]||(s[5]=t("作者：",-1)),a(e,{href:"https://insights.ubuntu.com/author/mathieu-trudel-lapierre/"},{default:n(()=>[...s[2]||(s[2]=[t("Mathieu Trudel-Lapierre",-1)])]),_:1}),s[6]||(s[6]=t(" 译者：",-1)),a(e,{href:"https://vicyu.com"},{default:n(()=>[...s[3]||(s[3]=[t("VicYu",-1)])]),_:1}),s[7]||(s[7]=t(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[4]||(s[4]=[t("wxy",-1)])]),_:1})]),i("p",null,[s[10]||(s[10]=t("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[8]||(s[8]=[t("LCTT",-1)])]),_:1}),s[11]||(s[11]=t(" 原创编译，",-1)),a(e,{href:"https://linux.cn/"},{default:n(()=>[...s[9]||(s[9]=[t("Linux中国",-1)])]),_:1}),s[12]||(s[12]=t(" 荣誉推出",-1))])])}const S=p(c,[["render",h]]);export{C as __pageData,S as default};
